    {
     "h": {
      "ar": "أعمدة جديدة ونصوص وتواريخ",
      "en": "New columns, text and dates"
     },
     "p": {
      "ar": "`assign(revenue=lambda d: d.qty * d.price)` بيضيف أعمدة في سلسلة. `map({...})` بيحوّل قيم بقاموس، و`np.where(cond, a, b)` (أو `.where`) if في عمود. و`.str.lower()` و`.str.contains(\"x\")` و`.str.strip()` على عمود نصوص كامل، و`.dt.month` و`.dt.day_name()` و`.dt.to_period(\"M\")` على التواريخ.",
      "en": "`assign(revenue=lambda d: d.qty * d.price)` adds columns in a chain. `map({...})` converts values with a dict, and `np.where(cond, a, b)` (or `.where`) is an if over a column. `.str.lower()`, `.str.contains(\"x\")` and `.str.strip()` work on a whole text column, and `.dt.month`, `.dt.day_name()` and `.dt.to_period(\"M\")` on dates."
     },
     "ex": "import io\nimport pandas as pd\ncsv_text = \"\"\"day,branch,product,category,qty,price,customer\n2026-09-01,Cairo,Pen,stationery,10,7.5,Sara\n2026-09-01,Giza,Bag,bags,1,650,Omar\n2026-09-02,Cairo,Bag,bags,2,650,Mona\n2026-09-02,Alex,Notebook,stationery,5,45,Hany\n2026-09-03,Cairo,Notebook,stationery,3,45,Sara\n2026-09-03,Giza,Pen,stationery,20,7.5,Laila\n2026-09-04,Alex,Sleeve,bags,2,320,Omar\n2026-09-05,Cairo,Sleeve,bags,1,320,Karim\n2026-10-01,Cairo,Bag,bags,3,650,Sara\n2026-10-02,Giza,Notebook,stationery,8,45,Mona\n\"\"\"\ndf = pd.read_csv(io.StringIO(csv_text), parse_dates=[\"day\"])\nimport numpy as np\nout = (df.assign(revenue=lambda d: d.qty * d.price,\n                 size=lambda d: np.where(d.qty * d.price >= 1000, \"big\", \"small\"),\n                 month=lambda d: d.day.dt.to_period(\"M\").astype(str),\n                 weekday=lambda d: d.day.dt.day_name(),\n                 branch_code=lambda d: d.branch.map({\"Cairo\": \"CAI\", \"Giza\": \"GIZ\", \"Alex\": \"ALX\"})))\nprint(out[[\"month\", \"weekday\", \"branch_code\", \"revenue\", \"size\"]].head(5))\nprint(out[out[\"product\"].str.contains(\"Note\")][\"customer\"].str.upper().tolist())",
     "run": 1
    }
