     "p": "import pandas as pd\n\ndef clean_sales(df: pd.DataFrame) -> tuple[pd.DataFrame, dict]:\n    report = {\"rows_in\": len(df)}\n    df = df.copy()\n    df.columns = df.columns.str.strip().str.lower().str.replace(\" \", \"_\")\n    for col in [\"qty\", \"price\"]:\n        df[col] = pd.to_numeric(df[col].astype(str).str.replace(r\"[^\\d.]\", \"\", regex=True), errors=\"coerce\")\n    df[\"day\"] = pd.to_datetime(df[\"day\"], errors=\"coerce\", format=\"mixed\", dayfirst=True)\n    report[\"bad_values\"] = int(df[[\"qty\", \"price\", \"day\"]].isna().sum().sum())\n    df = df.dropna(subset=[\"qty\", \"price\", \"day\"]).drop_duplicates()\n    report[\"rows_out\"] = len(df)\n    return df, report\n\nraw = pd.DataFrame({\" Day\": [\"2026-09-01\", \"02/09/2026\", \"x\"], \"Qty \": [\"2\", \"1\", \"3\"], \"price\": [\"650\", \"EGP 45\", \"7.5\"]})\nprint(clean_sales(raw))",
