     "ex": "import time\nimport numpy as np\nimport pandas as pd\nn = 200_000\ndf = pd.DataFrame({\"qty\": np.random.default_rng(1).integers(1, 10, n), \"price\": np.random.default_rng(2).choice([7.5, 45, 650], n)})\nt = time.perf_counter()\nslow = [row.qty * row.price for row in df.itertuples()]\nt_loop = time.perf_counter() - t\nt = time.perf_counter()\nfast = df.qty * df.price\nt_vec = time.perf_counter() - t\nprint(f\"loop {t_loop * 1000:.0f} ms, vectorised {t_vec * 1000:.1f} ms, same: {np.allclose(slow, fast)}\")",
